class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(dict.fromkeys(members))  # preserve order, drop dupes
        self.expenses: list[tuple[str, float, list[str]]] = []

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if amount <= 0:
            raise ValueError("Expense amount must be positive.")
        if payer not in self.members:
            raise ValueError(f"Unknown payer: {payer}")
        if participants is None:
            participants = list(self.members)
        else:
            participants = list(dict.fromkeys(participants))
            for p in participants:
                if p not in self.members:
                    raise ValueError(f"Unknown participant: {p}")
            if not participants:
                raise ValueError("Participants list must not be empty.")
        self.expenses.append((payer, float(amount), participants))

    def _cents(self, amount: float) -> int:
        return int(round(amount * 100))

    def balances(self) -> dict[str, float]:
        cents = {m: 0 for m in self.members}
        for payer, amount, participants in self.expenses:
            total = self._cents(amount)
            n = len(participants)
            share = total // n  # floor division in cents
            remainder = total - share * n
            # Payer paid the whole amount.
            cents[payer] += total
            # Each participant owes their share.
            # The remainder is "borne by the payer": participants pay only the
            # rounded-down share; the payer effectively absorbs the leftover.
            for p in participants:
                cents[p] -= share
            # Note: the payer is also a participant if included in the list and
            # will be charged their share via the loop above. The remainder is
            # not charged to anyone, so the payer ends up covering it.
        return {m: cents[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        bal_cents = {m: self._cents(b) for m, b in self.balances().items()}

        debtors = [[m, -bal_cents[m]] for m in self.members if bal_cents[m] < 0]
        creditors = [[m, bal_cents[m]] for m in self.members if bal_cents[m] > 0]

        # Sort deterministically for stable output.
        debtors.sort(key=lambda x: (-x[1], x[0]))
        creditors.sort(key=lambda x: (-x[1], x[0]))

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            d_name, d_amt = debtors[i]
            c_name, c_amt = creditors[j]
            pay = min(d_amt, c_amt)
            if pay >= 100:  # at least 1.00
                payments.append((d_name, c_name, pay / 100.0))
            d_amt -= pay
            c_amt -= pay
            if d_amt == 0:
                i += 1
            else:
                debtors[i][1] = d_amt
            if c_amt == 0:
                j += 1
            else:
                creditors[j][1] = c_amt

        return payments
